import type { Embedding, ProviderMetadata } from '../types';
import type { EmbeddingModelUsage } from '../types/usage';
import type { Warning } from '../types/warning';

/**
 * The result of one underlying embedding model call.
 */
export interface EmbedManyCall {
  /**
   * The inclusive index of the first input value for this call.
   */
  readonly startIndex: number;

  /**
   * The exclusive index after the last input value for this call.
   */
  readonly endIndex: number;

  /**
   * The embeddings generated by this call.
   */
  readonly embeddings: Array<Embedding>;

  /**
   * The embedding token usage for this call.
   */
  readonly usage: EmbeddingModelUsage;

  /**
   * Warnings for this call, e.g. unsupported settings.
   */
  readonly warnings: Array<Warning>;

  /**
   * Optional provider-specific metadata for this call.
   */
  readonly providerMetadata?: ProviderMetadata;

  /**
   * Optional raw response data for this call.
   */
  readonly response?: {
    /**
     * Response headers.
     */
    headers?: Record<string, string>;

    /**
     * The response body.
     */
    body?: unknown;
  };
}

/**
 * The result of an `embedMany` call.
 * It contains the embeddings, the values, and additional information.
 */
export interface EmbedManyResult {
  /**
   * The values that were embedded.
   */
  readonly values: Array<string>;

  /**
   * The embeddings. They are in the same order as the values.
   */
  readonly embeddings: Array<Embedding>;

  /**
   * The results of the underlying embedding model calls, in input order.
   */
  readonly calls: Array<EmbedManyCall>;

  /**
   * The embedding token usage.
   */
  readonly usage: EmbeddingModelUsage;

  /**
   * Warnings for the call, e.g. unsupported settings.
   */
  readonly warnings: Array<Warning>;

  /**
   * Optional provider-specific metadata.
   */
  readonly providerMetadata?: ProviderMetadata;

  /**
   * Optional raw response data.
   */
  readonly responses?: Array<EmbedManyCall['response']>;
}
